const cashData = $('GET Demo Cash1').item.json;
const bubbleData = $input.item.json;
const market = $('Check Market Conditions1').item.json;

// Safe portfolio read
let positions = [];
try {
  positions = $('GET Demo Portfolio1').all().map(i => i.json).filter(p => p && p.quantity > 0);
} catch(e) { positions = []; }

const cash = cashData.free || 0;
const marketContext = market.answer || (market.results || []).slice(0,2).map(r => r.content).join(' ') || '';
const bubbleContext = bubbleData.answer || (bubbleData.results || []).slice(0,3).map(r => r.content).join(' ') || '';

// === BUBBLE SCORE (0-15, based on Minsky/Kindleberger framework) ===
let bubbleScore = 0;
const combined = (marketContext + ' ' + bubbleContext).toLowerCase();

// VIX signals (fear/greed)
if (combined.includes('vix') && (combined.includes('below 15') || combined.includes('vix 12') || combined.includes('vix 13') || combined.includes('vix 14'))) {
  bubbleScore += 3; // extreme complacency
} else if (combined.includes('vix') && (combined.includes('above 30') || combined.includes('vix 35') || combined.includes('vix 40'))) {
  bubbleScore -= 1; // fear = buying opportunity not bubble
}

// Euphoria language
const euphoriaWords = ['all-time high', 'record high', 'irrational exuberance', 'melt up', 'parabolic', 'euphoria', 'mania', 'frenzy', 'bubble'];
euphoriaWords.forEach(w => { if (combined.includes(w)) bubbleScore += 1; });

// Fear/correction language (reduces score)
const fearWords = ['correction', 'bear market', 'recession', 'crash', 'selloff', 'downturn', 'contraction'];
fearWords.forEach(w => { if (combined.includes(w)) bubbleScore -= 1; });

// Valuation concerns
if (combined.includes('overvalued') || combined.includes('stretched valuation') || combined.includes('high p/e')) bubbleScore += 2;
if (combined.includes('undervalued') || combined.includes('cheap') || combined.includes('value stocks')) bubbleScore -= 1;

// Market breadth
if (combined.includes('narrowing breadth') || combined.includes('few stocks leading')) bubbleScore += 2;
if (combined.includes('broad rally') || combined.includes('broad market')) bubbleScore -= 1;

// Cap bubble score
bubbleScore = Math.max(0, Math.min(15, bubbleScore));

// Risk phase based on score
let riskPhase, aggressionMultiplier, riskColor;
if (bubbleScore <= 4) {
  riskPhase = 'Normal 🟢';
  aggressionMultiplier = 1.0; // full aggression
  riskColor = 'green';
} else if (bubbleScore <= 7) {
  riskPhase = 'Caution 🟡';
  aggressionMultiplier = 0.75; // reduce position sizes 25%
  riskColor = 'yellow';
} else if (bubbleScore <= 9) {
  riskPhase = 'Elevated Risk 🟠';
  aggressionMultiplier = 0.5; // reduce position sizes 50%
  riskColor = 'orange';
} else if (bubbleScore <= 12) {
  riskPhase = 'Euphoria 🔴';
  aggressionMultiplier = 0.25; // very small positions only
  riskColor = 'red';
} else {
  riskPhase = 'Critical ⛔';
  aggressionMultiplier = 0; // no new buys
  riskColor = 'critical';
}

// Market safe check (bearish keywords)
const bearishKeywords = ['crash', 'panic', 'circuit breaker', 'halted', 'black monday', 'recession fears', 'market meltdown'];
const isBearishMarket = bearishKeywords.some(k => combined.includes(k));
const marketSafe = !isBearishMarket && bubbleScore < 13;

const totalValue = positions.reduce((s,p) => s + ((p.currentPrice||0)*(p.quantity||0)), 0);
const totalPnl = positions.reduce((s,p) => s + (p.ppl||0), 0);

return [{json: {
  cash: parseFloat(cash.toFixed(2)),
  openPositions: positions,
  positionCount: positions.length,
  hasPositions: positions.length > 0,
  totalValue: parseFloat(totalValue.toFixed(2)),
  totalPnl: parseFloat(totalPnl.toFixed(2)),
  marketContext: marketContext.substring(0, 300),
  bubbleContext: bubbleContext.substring(0, 300),
  bubbleScore,
  riskPhase,
  aggressionMultiplier,
  isBearishMarket,
  marketSafe
}}];

const state = $('Store State + Market Check1').item.json;
const positions = state.openPositions;

const systemPrompt = `You are a swing trade manager targeting £20/day profit from a £100 demo account.

SELL RULES (tight targets for daily profits):
- Sell immediately if position is up 4%+ (take profit — lock in the gain)
- Sell if position is up 3%+ AND it has been held over 12 hours (don't get greedy)
- Sell immediately if position is down 2.5%+ (stop loss — protect the pot)
- Sell if RSI is now above 68 even if only up 2% (momentum fading, exit)
- HOLD if up 1-2% and momentum still strong (let it run to 4%)
- HOLD if down less than 2% and oversold bounce still in play

GOAL: Small consistent wins. £20/day target. Never let a winner turn into a loser.

Return ONLY valid JSON:
{"decisions":[{"ticker":"MARA_US_EQ","action":"SELL","reason":"Up 4.2% - take profit hit"},{"ticker":"IONQ_US_EQ","action":"HOLD","reason":"Up 1.8% - momentum still strong"}]}`;

const userPrompt = `OPEN POSITIONS:
${JSON.stringify(positions.map(p => ({
  ticker: p.ticker,
  quantity: p.quantity,
  entryPrice: p.averagePrice,
  currentPrice: p.currentPrice,
  pnlPct: p.averagePrice ? (((p.currentPrice - p.averagePrice) / p.averagePrice) * 100).toFixed(2) + '%' : '0%',
  pnl: p.ppl || 0
})), null, 2)}

Apply the sell rules. Be disciplined. Return JSON only.`;

return [{json: {systemPrompt, userPrompt, positions}}];

const raw = $input.item.json.content ||
    $input.item.json.message?.content || '';
const positions = $('Build Sell Prompt1').item.json.positions;

// Robust parser for deepseek output
let decisions = [];
try {
    let cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
    let parsed;
    try {
          parsed = JSON.parse(cleaned);
    } catch(e1) {
          try {
                  parsed = JSON.parse('[' + cleaned + ']');
          } catch(e2) {
                  parsed = {decisions: []};
          }
    }
    if (Array.isArray(parsed)) {
          decisions = parsed;
    } else if (parsed && Array.isArray(parsed.decisions)) {
          decisions = parsed.decisions;
    } else if (parsed && parsed.ticker) {
          decisions = [parsed];
    }
} catch(e) {
    decisions = [];
}

const sells = decisions
  .filter(d => d.action === 'SELL')
  .map(d => {
        const pos = positions.find(p => p.ticker === d.ticker);
        return {
                ticker: d.ticker,
                quantity: pos ? pos.quantity : 0,
                reason: d.reason,
                currentPrice: pos ? pos.currentPrice : 0,
                entryPrice: pos ? pos.averagePrice : 0,
                pnlPct: pos && pos.averagePrice ?
                          (((pos.currentPrice - pos.averagePrice) / pos.averagePrice) * 100).toFixed(2) + '%' : '0',
                pnl: pos ? pos.ppl : 0
        };
  })
  .filter(d => d.quantity > 0);

return [{json: {sells, sellCount: sells.length, hasSells: sells.length > 0}}];

