const chart = data.chart;
const result = chart?.result?.[0];

if (!result) return {json: {ticker, name, skip: true, skipReason: 'No chart data'}};

const closes = (result.indicators?.quote?.[0]?.close || []).filter(c => c !== null && c !== undefined);
const volumes = (result.indicators?.quote?.[0]?.volume || []).filter(v => v !== null && v !== undefined);
const meta = result.meta || {};

if (closes.length < 5) return {json: {ticker, name, skip: true, skipReason: 'Not enough price data'}};

let currentPrice = meta.regularMarketPrice || closes[closes.length - 1];
const currency = meta.currency || '';
if (currency === 'GBX' || currency === 'GBp' || currentPrice > 500) currentPrice = currentPrice / 100;

const price5dAgo = closes[closes.length - 6] || closes[0];
const change5d = ((currentPrice - price5dAgo) / price5dAgo) * 100;
const change1d = closes.length >= 2 ? ((closes[closes.length-1] - closes[closes.length-2]) / closes[closes.length-2]) * 100 : 0;

// RSI calculation
const recentCloses = closes.slice(-14);
let gains = 0, losses = 0;
for (let i = 1; i < recentCloses.length; i++) {
  const diff = recentCloses[i] - recentCloses[i-1];
  if (diff > 0) gains += diff; else losses += Math.abs(diff);
}
const periods = recentCloses.length - 1;
const avgGain = periods > 0 ? gains / periods : 0;
const avgLoss = periods > 0 ? losses / periods : 1;
const rs = avgLoss === 0 ? 100 : avgGain / avgLoss;
const rsi = parseFloat((100 - (100 / (1 + rs))).toFixed(1));

// Volume spike
const recentVols = volumes.slice(-5).filter(v => v > 0);
const avgVol = recentVols.length > 0 ? recentVols.reduce((a,b) => a+b,0) / recentVols.length : 1;
