const volumeSpike = parseFloat((latestVol / avgVol).toFixed(2));

let dipScore = 0;
let signals = [];

// RELAXED: RSI requirements are much easier to hit now
if (rsi < 35) { dipScore += 45; signals.push('RSI very oversold: ' + rsi); }
else if (rsi < 45) { dipScore += 30; signals.push('RSI oversold: ' + rsi); }
else if (rsi < 55) { dipScore += 15; signals.push('RSI dipping: ' + rsi); } // NEW: Catches mild dips

