else if (change5d < -4) { dipScore += 22; signals.push('Down ' + Math.abs(change5d).toFixed(1) + '% in 5 days'); }
else if (change5d < -1.5) { dipScore += 10; signals.push('Down ' + Math.abs(change5d).toFixed(1) + '% in 5 days'); }

