const cashData = $('EOD: GET Cash1').item.json;
const positions = $('EOD: GET Portfolio1').all().map(i => i.json).filter(p => p && p.quantity > 0);

const cash = cashData.free || 0;
const currentValue = positions.reduce((s,p) => s + ((p.currentPrice||0)*(p.quantity||0)), 0);
const totalPnl = positions.reduce((s,p) => s + (p.ppl||0), 0);
const totalAccount = cash + currentValue;
const startingValue = 5000;

const positionsList = positions.length > 0
  ? positions.map(p => {
      const pnlPct = p.averagePrice ? (((p.currentPrice - p.averagePrice) / p.averagePrice) * 100).toFixed(1) : '0';
      return '• ' + p.ticker + ': ' + (pnlPct > 0 ? '📈' : '📉') + ' ' + pnlPct + '% ($' + (p.ppl||0).toFixed(2) + ')';
    }).join('\n')
  : '• No open positions';

const diff = (totalAccount - startingValue).toFixed(2);
const diffPct = (((totalAccount - startingValue) / startingValue) * 100).toFixed(1);
const targetStatus = totalPnl >= 20 ? '✅ TARGET HIT!' : totalPnl >= 10 ? '🟡 Halfway there' : totalPnl >= 0 ? '🔵 Positive but below target' : '🔴 In the red today';

const report = '📊 **SWING BOT — Daily P&L Report**\n🕐 ' + new Date().toLocaleString('en-GB') + '\n________________\n\n' +
  '💰 **Account Summary:**\n' +
  '• Total value: $' + totalAccount.toFixed(2) + '\n' +
  '• Free cash: $' + cash.toFixed(2) + '\n' +
  '• Open positions: ' + positions.length + '\n' +
  '• Unrealised P&L: ' + (totalPnl >= 0 ? '+' : '') + '$' + totalPnl.toFixed(2) + '\n' +
  '• vs Start ($5000): ' + (totalAccount >= startingValue ? '+' : '') + '$' + diff + ' (' + diffPct + '%)\n\n' +
  '📈 **Open Positions:**\n' + positionsList + '\n\n' +
  '🎯 **Daily Target:** $20 profit\n' + targetStatus + '\n________________';

return [{json: {report}}];

// Circuit Breaker — checks if bot should be trading at all
const state = $('Store State + Market Check1').item.json;
const cash = state.cash;
const totalValue = state.totalValue;
const totalAccount = cash + totalValue;

// Read trade log to calculate performance metrics
let tradeLog = '';
try {
  tradeLog = $('Read Trade Log CSV1').item.json.stdout || '';
} catch(e) { tradeLog = ''; }

// Parse CSV trades
const lines = tradeLog.split('\n').filter(l => l.includes(','));
const trades = lines.map(l => {
  const parts = l.split(',');
  return {
    date: parts[0],
    ticker: parts[1],
    action: parts[2],
    price: parseFloat(parts[3]) || 0,
    pnlPct: parseFloat(parts[4]) || 0,
    pnl: parseFloat(parts[5]) || 0
  };
}).filter(t => t.action === 'SELL');

// Calculate metrics
const totalTrades = trades.length;
const winners = trades.filter(t => t.pnl > 0);
const losers = trades.filter(t => t.pnl <= 0);
const winRate = totalTrades > 0 ? ((winners.length / totalTrades) * 100).toFixed(1) : 0;
const totalPnl = trades.reduce((s, t) => s + t.pnl, 0);
const avgWin = winners.length > 0 ? winners.reduce((s,t) => s+t.pnl, 0) / winners.length : 0;
const avgLoss = losers.length > 0 ? Math.abs(losers.reduce((s,t) => s+t.pnl, 0) / losers.length) : 0;
const profitFactor = avgLoss > 0 ? (avgWin / avgLoss).toFixed(2) : 'N/A';

// Get recent trades for consecutive loss check
const recentTrades = trades.slice(-5);
const consecutiveLosses = (() => {
  let count = 0;
  for (let i = recentTrades.length - 1; i >= 0; i--) {
    if (recentTrades[i].pnl <= 0) count++;
    else break;
  }
  return count;
})();

// Get today's trades
const today = new Date().toISOString().split('T')[0];
const todayTrades = trades.filter(t => t.date && t.date.startsWith(today));
const todayPnl = todayTrades.reduce((s, t) => s + t.pnl, 0);

// CIRCUIT BREAKER RULES
const startingValue = 5000; // demo starting amount
const peakValue = Math.max(startingValue, totalAccount); // simplified - ideally track this separately
const drawdownFromStart = ((startingValue - totalAccount) / startingValue) * 100;

let circuitBreakerTriggered = false;
let pauseReason = '';

// Rule 1: Max drawdown 15% from starting value
if (drawdownFromStart >= 15) {
  circuitBreakerTriggered = true;
  pauseReason = 'MAX DRAWDOWN: Account down ' + drawdownFromStart.toFixed(1) + '% from start ($' + startingValue + ')';
}

// Rule 2: 3 consecutive losses
if (consecutiveLosses >= 3) {
  circuitBreakerTriggered = true;
  pauseReason = 'CONSECUTIVE LOSSES: ' + consecutiveLosses + ' losses in a row — strategy not working right now';
}

// Rule 3: Daily trade count limit (6 per day)
if (todayTrades.length >= 6) {
  circuitBreakerTriggered = true;
  pauseReason = 'DAILY TRADE LIMIT: ' + todayTrades.length + ' trades today — pausing to avoid overtrading';
}

// Rule 4: Daily loss limit (5% of account)
const dailyLossLimit = totalAccount * 0.05;
if (todayPnl < -dailyLossLimit) {
  circuitBreakerTriggered = true;
  pauseReason = 'DAILY LOSS LIMIT: Lost $' + Math.abs(todayPnl).toFixed(2) + ' today (limit: $' + dailyLossLimit.toFixed(2) + ')';
}

return [{json: {
  ...state,
  circuitBreakerTriggered,
  pauseReason,
  metrics: {
    totalTrades,
    winRate,
    totalPnl: totalPnl.toFixed(2),
    profitFactor,
    consecutiveLosses,
    todayTrades: todayTrades.length,
    todayPnl: todayPnl.toFixed(2),
    drawdownFromStart: drawdownFromStart.toFixed(1)
  }
}}];

const tradeLog = $input.item.json.stdout || '';
const lines = tradeLog.split('\n').filter(l => l.includes(',') && !l.startsWith('Date'));

const trades = lines.map(l => {
  const parts = l.split(',');
  return {
    date: parts[0],
    ticker: parts[1],
    action: parts[2],
    price: parseFloat(parts[3]) || 0,
    pnlPct: parseFloat(parts[4]) || 0,
    pnl: parseFloat(parts[5]) || 0,
    score: parseFloat(parts[8]) || 0
  };
}).filter(t => t.action === 'SELL' && !isNaN(t.pnl));

if (trades.length === 0) {
  return [{json: {report: '📊 **Weekly Performance Report**\nNo closed trades yet this week.'}}];
}

const winners = trades.filter(t => t.pnl > 0);
const losers = trades.filter(t => t.pnl <= 0);
const totalPnl = trades.reduce((s,t) => s + t.pnl, 0);
const winRate = ((winners.length / trades.length) * 100).toFixed(1);
const avgWin = winners.length > 0 ? (winners.reduce((s,t) => s+t.pnl, 0) / winners.length).toFixed(2) : 0;
const avgLoss = losers.length > 0 ? Math.abs((losers.reduce((s,t) => s+t.pnl, 0) / losers.length)).toFixed(2) : 0;
const profitFactor = avgLoss > 0 ? (avgWin / avgLoss).toFixed(2) : 'N/A';

// Sharpe ratio (simplified - daily returns)
const returns = trades.map(t => t.pnlPct);
const avgReturn = returns.reduce((s,r) => s+r, 0) / returns.length;
const stdDev = Math.sqrt(returns.reduce((s,r) => s + Math.pow(r - avgReturn, 2), 0) / returns.length);
const sharpe = stdDev > 0 ? (avgReturn / stdDev).toFixed(2) : 'N/A';

// Best and worst trades
const best = trades.reduce((a,b) => a.pnl > b.pnl ? a : b);
const worst = trades.reduce((a,b) => a.pnl < b.pnl ? a : b);

// Weekly trades (last 7 days)
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);
const weekTrades = trades.filter(t => new Date(t.date) >= weekAgo);
const weekPnl = weekTrades.reduce((s,t) => s + t.pnl, 0);

const perfEmoji = totalPnl >= 20 ? '🟢' : totalPnl >= 0 ? '🟡' : '🔴';

const report = '📊 **SWING BOT — Weekly Performance Report**\n' +
  '🕐 ' + new Date().toLocaleString('en-GB') + '\n________________\n\n' +
  '**This Week:**\n' +
  '• Trades: ' + weekTrades.length + '\n' +
  '• P&L: ' + (weekPnl >= 0 ? '+' : '') + '$' + weekPnl.toFixed(2) + '\n' +
  '• vs £20/day target: ' + (weekPnl >= 100 ? '✅ TARGET HIT' : weekPnl >= 50 ? '🟡 Halfway' : '🔴 Below target') + '\n\n' +
  '**All Time Stats:**\n' +
  '• Total closed trades: ' + trades.length + '\n' +
  '• Win rate: ' + winRate + '% (' + winners.length + 'W / ' + losers.length + 'L)\n' +
  '• Total P&L: ' + (totalPnl >= 0 ? '+' : '') + '$' + totalPnl.toFixed(2) + '\n' +
  '• Avg win: $' + avgWin + ' | Avg loss: $' + avgLoss + '\n' +
  '• Profit factor: ' + profitFactor + ' (>1.5 = good)\n' +
  '• Sharpe ratio: ' + sharpe + ' (>1.0 = good)\n\n' +
  '**Best trade:** ' + best.ticker + ' +$' + best.pnl.toFixed(2) + '\n' +
  '**Worst trade:** ' + worst.ticker + ' $' + worst.pnl.toFixed(2) + '\n________________';

return [{json: {report}}];

