  if (!inst.ticker || !inst.ticker.endsWith('_US_EQ')) return false;
  if (inst.currencyCode !== 'USD') return false;
  if (!inst.name && !inst.shortName) return false;
  if (excludedTickers.some(ex => inst.ticker.includes(ex))) return false;

