// Appends each sell decision as a training example to unsloth_feedback.jsonl
const fs = require('fs');
const path = '/home/c1-pop/mounts/zimablade-trading/unsloth_feedback.jsonl';

const results = [];

for (const item of $input.all()) {
    const d = item.json;

    // Determine if this was a good or bad decision
    const pnl = parseFloat(d.pnl) || 0;
    const outcome = pnl >= 0 ? 'GOOD_SELL' : 'BAD_SELL';
    const quality = pnl >= 0 ? 'correct' : 'premature or incorrect';

    // Build a training example in Alpaca format for Unsloth
    const trainingExample = {
          timestamp: new Date().toISOString(),
          instruction: "You are a swing trading AI. Analyze this position and decide: SELL or HOLD.",
          input: `Ticker: ${d.ticker}, Current Price: ${d.currentPrice}, Entry Price: ${d.entryPrice || 'unknown'}, PnL%: ${d.pnlPct}, RSI context available.`,
          output: `{"action": "SELL", "reason": "${(d.reason || '').replace(/"/g, "'")}"}`,
          outcome: outcome,
          pnl: pnl,
          feedback: `This sell was ${quality}. PnL: ${pnl}`
    };

    // Append to JSONL file
    try {
          fs.appendFileSync(path, JSON.stringify(trainingExample) + '\n');
    } catch(e) {
          // File write failed - log but don't crash workflow
          console.log('Feedback write error:', e.message);
    }

    results.push({ json: { ...d, feedbackLogged: true, outcome } });
}

return results;
